<?php
require_once __DIR__.'/analytics_charts.php';require_once __DIR__.'/job_report_export.php';
function anExportName(array $data,string $extension): string {return 'TheCelandine_'.($data['scope']==='all'?'Analytics':ucfirst($data['scope']).'Analytics').'_'.$data['period']['filename'].'.'.$extension;}
function anExportLimit(): int {
    $configured=max(100,min(1500,(int)appSetting('CONDO_ANALYTICS_EXPORT_MAX_ROWS','500')));$setting=trim((string)ini_get('memory_limit'));if($setting==='-1')return $configured;$unit=strtolower(substr($setting,-1));$memory=(int)$setting*match($unit){'g'=>1073741824,'m'=>1048576,'k'=>1024,default=>1};return max(10,min($configured,(int)floor(max(0,$memory-memory_get_usage(true)-100663296)/786432)));
}
function anExportGuard(array $data): void {
    $rows=0;foreach($data['sections']as$s){$rows+=count($s['metrics']);foreach($s['charts']as$c)$rows+=count($c['rows'])*(isset($c['secondary'])?2:1);}if($rows>anExportLimit())throw new DomainException('This complete report exceeds the current '.anExportLimit().' aggregate-row rendering limit. Use Monthly/Yearly grouping, a narrower period, or a specific report scope. No analytics rows were omitted.');
}
function anReportHtml(array $data): string {
    $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$html='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>System Analytics Report</title><style>'.brandDocumentStyles().'@page{margin:30px 30px 42px}body{font:9px "DejaVu Sans",sans-serif;color:#182236;background:#fff}h1{font-size:22px;margin:16px 0 8px}h2{font-size:17px;margin:20px 0 10px;color:#b45309;page-break-after:avoid}h3{font-size:12px;margin:18px 0 7px;page-break-after:avoid}p{line-height:1.6;word-wrap:break-word}.section{page-break-before:always}.rule{border-top:2px solid #d97706;margin-top:12px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin-bottom:12px}thead{display:table-header-group}tr{page-break-inside:avoid}th,td{text-align:left;vertical-align:top;padding:6px;border-bottom:1px solid #dce3ed;word-wrap:break-word;line-height:1.5}th{background:#f3f6fa;color:#526176}.chart{page-break-inside:avoid}.chart img{width:680px;height:302px}.muted{font-size:8px;color:#526176}.unavailable{color:#9a3412}</style></head><body>'.brandDocumentHtml(34).'<div class="rule"></div><h1>SYSTEM ANALYTICS REPORT</h1><p><strong>Reporting period:</strong> '.$e($data['period']['label']).'<br><strong>Activity cutoff:</strong> '.$e($data['period']['through']).' (Asia/Manila)<br><strong>Generated / data refreshed:</strong> '.$e($data['refreshed_at']).'<br><strong>Generated by:</strong> '.$e($data['actor']['name']).' / USER-'.$data['actor']['id'].'<br><strong>Scope:</strong> '.$e($data['scope']==='all'?'Entire authorized analytics report':$data['catalog'][$data['scope']]).'<br><strong>Grouping:</strong> '.$e($data['period']['group']).'<br><strong>Comparison:</strong> '.$e($data['period']['comparison_label']).'<br><strong>Staff lookup (staff section only):</strong> '.$e($data['filters']['staff_q']?:'All names / IDs').' / '.$e($data['filters']['staff_role']?:'All staff roles').'</p><p class="muted">Live state, period events and unavailable historical balances are distinguished for every metric. Unknown data is never replaced with a successful zero calculation.</p>';
    foreach($data['sections']as$key=>$section){$html.='<div class="section"><h2>'.$e($data['catalog'][$key]).'</h2>';if(!$section['available']){$html.='<p class="unavailable">'.$e(implode(' ',$section['notes'])).'</p></div>';continue;}$html.='<table><thead><tr><th style="width:30%">Metric</th><th style="width:16%">Actual value</th><th style="width:24%">Time basis / context</th><th style="width:30%">Definition / comparison</th></tr></thead><tbody>';foreach($section['metrics']as$m){$description=$m['definition'];if($m['previous']!==null)$description.=' Previous: '.anFormat($m['previous'],$m['unit']).'; change: '.anFormat($m['change'],$m['unit']).'; percentage: '.($m['percent_change']===null?'Unavailable (zero baseline)':$m['percent_change'].'%').'.';$html.='<tr><td>'.$e($m['label']).'</td><td>'.$e(anFormat($m['value'],$m['unit'])).'</td><td>'.$e($m['context']).'</td><td>'.$e($description).'</td></tr>';}$html.='</tbody></table>';foreach($section['notes']as$note)$html.='<p class="muted">'.$e($note).'</p>';
        foreach($section['charts']as$c){$svg=anChartSvg($c,true);$html.='<div class="chart"><h3>'.$e($c['title']).'</h3><img src="data:image/svg+xml;base64,'.base64_encode($svg).'" alt="'.$e($c['title']).'"></div><table><thead><tr><th>Category / time bucket</th><th>'.$e($c['primary_name']??'Value').'</th>'.(isset($c['secondary'])?'<th>'.$e($c['secondary_name']).'</th>':'').'</tr></thead><tbody>';foreach($c['rows']as$i=>$r)$html.='<tr><td>'.$e($r['label']).'</td><td>'.$e(anFormat($r['value'],$c['unit'])).'</td>'.(isset($c['secondary'])?'<td>'.$e(anFormat($c['secondary'][$i]['value']??0,$c['unit'])).'</td>':'').'</tr>';if(!$c['rows'])$html.='<tr><td colspan="2">No matching records for this chart.</td></tr>';$html.='</tbody></table>';}$html.='</div>';
    }
    $html.='<div class="section"><h2>Management Insights</h2>';foreach($data['insights']as$i)$html.='<h3>'.$e($i['title']).'</h3><p>'.$e($i['metric']).': '.$e(anFormat($i['value'],$i['unit'])).'<br>'.$e($i['context']).'<br>'.$e($i['rule']).'</p>';return $html.'<p class="muted">THE CELANDINE - Confidential authorized management report. No private resident identities, QR credentials, complaint evidence or staff work notes are included.</p></div></body></html>';
}
function anPdf(array $data): string {
    anExportGuard($data);$options=new Dompdf\Options();$options->set('isRemoteEnabled',false);$options->set('isPhpEnabled',false);$options->setChroot(dirname(__DIR__));$pdf=new Dompdf\Dompdf($options);$pdf->loadHtml(anReportHtml($data),'UTF-8');$pdf->setPaper('A4','landscape');$pdf->render();brandPdfFooter($pdf, 'Confidential analytics report');return $pdf->output();
}
function anPngPages(array $data): Generator {
    $exportGenerated = brandGeneratedAt();
    anExportGuard($data);if(!extension_loaded('gd')||!function_exists('imagettftext'))throw new RuntimeException('PNG export requires GD/FreeType.');$font=dirname(__DIR__).'/vendor/dompdf/dompdf/lib/fonts/DejaVuSans.ttf';$bold=dirname(__DIR__).'/vendor/dompdf/dompdf/lib/fonts/DejaVuSans-Bold.ttf';$lines=[];
    $push=static function(string $text,int $size=16,bool $heavy=false)use(&$lines,$font,$bold){foreach(jrWrapLines($text,static function($s)use($size,$heavy,$font,$bold){$b=imagettfbbox($size,0,$heavy?$bold:$font,$s);return max($b[0],$b[2],$b[4],$b[6])-min($b[0],$b[2],$b[4],$b[6])<=1080;})as$line)$lines[]=['kind'=>'text','text'=>$line,'size'=>$size,'heavy'=>$heavy,'height'=>(int)ceil($size*1.6)];};
    $push('SYSTEM ANALYTICS REPORT',24,true);$push('Period: '.$data['period']['label'],17,true);$push('Activity cutoff: '.$data['period']['through'].' (Asia/Manila)',14);$push('Generated by: '.$data['actor']['name'].' / USER-'.$data['actor']['id'],14);$push('Data refreshed: '.$data['refreshed_at'],14);$push('Scope: '.($data['scope']==='all'?'Entire authorized report':$data['catalog'][$data['scope']]),14);$push('Grouping: '.$data['period']['group'].' | '.$data['period']['comparison_label'],13);$push('Staff filter (staff section only): '.($data['filters']['staff_q']?:'All').' / '.($data['filters']['staff_role']?:'All'),13);$push('');
    foreach($data['sections']as$key=>$s){$push($data['catalog'][$key],21,true);if(!$s['available']){foreach($s['notes']as$n)$push($n);continue;}foreach($s['metrics']as$m){$push($m['label'].': '.anFormat($m['value'],$m['unit']),16,true);$push($m['context'].($m['definition']?' | '.$m['definition']:''),13);if($m['previous']!==null)$push('Previous '.anFormat($m['previous'],$m['unit']).'; change '.anFormat($m['change'],$m['unit']).'; percentage '.($m['percent_change']===null?'Unavailable (zero baseline)':$m['percent_change'].'%'),13);}foreach($s['notes']as$n)$push($n,13);foreach($s['charts']as$c){$push($c['title'],18,true);$lines[]=['kind'=>'chart','chart'=>$c,'height'=>310];foreach($c['rows']as$i=>$r)$push($r['label'].' | '.anFormat($r['value'],$c['unit']).(isset($c['secondary'])?' | '.$c['secondary_name'].': '.anFormat($c['secondary'][$i]['value']??0,$c['unit']):''),14);if(!$c['rows'])$push('No matching chart records.',14);$push('');}$push('');}
    $push('Management Insights',21,true);foreach($data['insights']as$i){$push($i['title'],17,true);$push($i['metric'].': '.anFormat($i['value'],$i['unit']).' | '.$i['context'],14);$push($i['rule'],13);}
    $chunks=[];$chunk=[];$height=0;foreach($lines as$i=>$line){$required=$line['height'];if($line['kind']==='text'&&$line['heavy']&&isset($lines[$i+1]))$required+=$lines[$i+1]['height'];if($chunk&&$height+$required>1430){$chunks[]=$chunk;$chunk=[];$height=0;}$chunk[]=$line;$height+=$line['height'];}if($chunk)$chunks[]=$chunk;
    foreach($chunks as$index=>$chunk){$im=imagecreatetruecolor(1240,1754);$ink=imagecolorallocate($im,24,34,54);$muted=imagecolorallocate($im,82,97,118);$orange=imagecolorallocate($im,180,83,9);imagefill($im,0,0,imagecolorallocate($im,255,255,255));brandImageHeader($im);$y=183;
        foreach($chunk as$line){if($line['kind']==='text')imagettftext($im,$line['size'],0,80,$y,$ink,$line['heavy']?$bold:$font,$line['text']);else anDrawPngChart($im,$line['chart'],90,$y,1060,280,$font);$y+=$line['height'];}brandImageFooter($im,$index+1,count($chunks),'Confidential',$exportGenerated);ob_start();imagepng($im);$bytes=(string)ob_get_clean();imagedestroy($im);yield ['number'=>$index+1,'total'=>count($chunks),'bytes'=>$bytes];}
}
function anDrawPngChart(GdImage $im,array $c,int $x,int $y,int $w,int $h,string $font): void {
    $rows=$c['rows'];$n=count($rows);$color=imagecolorallocate($im,217,119,6);$blue=imagecolorallocate($im,37,99,235);$muted=imagecolorallocate($im,82,97,118);$grid=imagecolorallocate($im,219,226,235);$max=max(array_merge([0],array_column($rows,'value'),array_column($c['secondary']??[],'value')));if(!$n||$max<=0){imagettftext($im,15,0,$x+20,$y+70,$muted,$font,'No matching chart values for this period.');return;}$min=min(array_merge([0],array_column($rows,'value')));$range=max(1,$max-$min);$left=$x+100;$plot=$w-120;$base=$y+$h-40;$height=$h-70;
    if(isset($c['secondary'])){imagettftext($im,11,0,$left,$y+12,$color,$font,$c['primary_name']);imagettftext($im,11,0,$left+440,$y+12,$blue,$font,$c['secondary_name']);}
    for($i=0;$i<=4;$i++){$yy=(int)round($base-$i*$height/4);imageline($im,$left,$yy,$left+$plot,$yy,$grid);imagettftext($im,10,0,$x,$yy+4,$muted,$font,anAxis($min+$range*$i/4,$c['unit']));}
    $series=[$rows];if(isset($c['secondary']))$series[]=$c['secondary'];foreach($series as$si=>$set){$last=null;foreach($set as$i=>$r){$xx=(int)round($left+($i+.5)*$plot/$n);$yy=(int)round($base-($r['value']-$min)/$range*$height);$cc=$si?$blue:$color;if($c['type']==='line'){if($last)imageline($im,$last[0],$last[1],$xx,$yy,$cc);imagefilledellipse($im,$xx,$yy,5,5,$cc);$last=[$xx,$yy];}else{$bw=max(1,(int)($plot/$n*.65/count($series)));$xx+=(int)(($si-.5)*$bw);$zero=(int)round($base-(-$min)/$range*$height);imagefilledrectangle($im,$xx,min($yy,$zero),$xx+$bw,max($yy,$zero),$cc);}}}
    $step=max(1,(int)ceil($n/6));foreach($rows as$i=>$r)if($i%$step===0)imagettftext($im,10,0,(int)($left+($i+.5)*$plot/$n-30),$base+22,$muted,$font,mb_strimwidth($r['label'],0,18,'...'));
}
function anDownload(mysqli $db,array $data,string $format): void {
    anExportGuard($data);$event=static function()use($db,$data,$format){if(!logAudit('export','analytics_export',null,strtoupper($format).'; scope '.$data['scope'].'; '.$data['period']['filename'],$db,'success'))throw new RuntimeException('Unable to record the analytics export.');};
    if($format==='pdf'){$bytes=anPdf($data);$event();header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.anExportName($data,'pdf').'"');echo $bytes;return;}
    if($format!=='png')throw new DomainException('Choose PDF or PNG.');$pages=anPngPages($data);$pages->rewind();$first=$pages->current();if($first['total']===1){$event();header('Content-Type: image/png');header('Content-Disposition: attachment; filename="'.anExportName($data,'png').'"');echo $first['bytes'];return;}if(!class_exists('ZipArchive'))throw new RuntimeException('Multiple PNG pages require PHP ZIP.');$directory=realpath(sys_get_temp_dir());if(!$directory)throw new RuntimeException('Private staging is unavailable.');foreach([dirname(__DIR__),dirname(__DIR__,2),$_SERVER['DOCUMENT_ROOT']??'']as$public)if($public&&realpath($public)&&visitorPathWithin($directory,realpath($public)))throw new RuntimeException('Export staging must be outside public directories.');$tmp=tempnam($directory,'condo-insights-');if(!$tmp)throw new RuntimeException('Private staging is unavailable.');$zip=new ZipArchive();$open=false;
    try{if(!chmod($tmp,0600)||$zip->open($tmp,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Unable to prepare report images.');$open=true;foreach($pages as$page)if(!$zip->addFromString(pathinfo(anExportName($data,'png'),PATHINFO_FILENAME).'_Part'.$page['number'].'.png',$page['bytes']))throw new RuntimeException('Unable to include every report page.');if(!$zip->close())throw new RuntimeException('Unable to finish report archive.');$open=false;$event();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.anExportName($data,'zip').'"');readfile($tmp);}finally{if($open)$zip->close();if(is_file($tmp))unlink($tmp);}
}
